using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.HighDefinition;using Object=UnityEngine.Object;
public static class FarmFinishing {
 const string A="Assets/NewMap/FiveHangars";static Transform root,exp;static Terrain terrain;static Dictionary<string,string> paths;static Material timber,metal,cream;
 static void Init(){root=GameObject.Find("New_Map").transform;exp=root.Find("11_Five_Hangar_Farm");terrain=root.GetComponentInChildren<Terrain>();paths=AssetDatabase.FindAssets("t:Prefab",new[]{"Assets/Imported/Toon Series/Toon Farm Pack/Prefabs"}).Select(AssetDatabase.GUIDToAssetPath).GroupBy(Path.GetFileNameWithoutExtension).ToDictionary(g=>g.Key,g=>g.First());timber=AssetDatabase.LoadAssetAtPath<Material>("Assets/NewMap/TallHangar/Rich oak framing.mat");cream=AssetDatabase.LoadAssetAtPath<Material>(A+"/Shop warm cream.mat");metal=AssetDatabase.LoadAssetAtPath<Material>("Assets/NewMap/TallHangar/Dark aged iron fasteners.mat");}
 static Transform Group(string n,Transform p){var g=new GameObject(n);g.transform.SetParent(p,false);return g.transform;}
 static float H(Vector3 p)=>terrain.SampleHeight(p)+terrain.transform.position.y;
 static GameObject Box(string n,Transform p,Vector3 pos,Vector3 size,Material m,bool collision=true){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=n;g.transform.SetParent(p,false);g.transform.localPosition=pos;g.transform.localScale=size;g.GetComponent<Renderer>().sharedMaterial=m;if(!collision)Object.DestroyImmediate(g.GetComponent<Collider>());return g;}
 static void Beam(Transform p,Vector3 a,Vector3 b,float w,Material m){var g=Box("Brace",p,(a+b)*.5f,new Vector3(w,(b-a).magnitude,w),m,false);g.transform.localRotation=Quaternion.FromToRotation(Vector3.up,b-a);}
 static GameObject Prefab(string n,Transform p,Vector3 pos,float yaw=0,float scale=1){var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(paths[n]),p);g.transform.SetPositionAndRotation(new Vector3(pos.x,H(pos),pos.z),Quaternion.Euler(0,yaw,0));g.transform.localScale=Vector3.one*scale;return g;}
 static void Save(){AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(terrain.gameObject.scene);}
 static void Text(string text,Transform parent,Vector3 pos,float fontSize,Vector2 size){var t=Group(text,parent);t.localPosition=pos;t.localRotation=Quaternion.Euler(0,180,0);var tm=t.gameObject.AddComponent<TMPro.TextMeshPro>();tm.text=text;tm.fontSize=fontSize;tm.color=new Color(.96f,.87f,.65f);tm.alignment=TMPro.TextAlignmentOptions.Center;tm.rectTransform.sizeDelta=size;tm.textWrappingMode=TMPro.TextWrappingModes.NoWrap;}
 public static string Doors(){Init();
  for(int i=2;i<=5;i++){var h=exp.Cast<Transform>().Single(t=>t.name.StartsWith("Hangar "+i+" -"));var shell=h.Find("Combined structure");foreach(var t in shell.Cast<Transform>().Where(t=>t.name.StartsWith("Door ")).ToArray())Object.DestroyImmediate(t.gameObject);
   var doors=Group(i<4?"Locked wooden doors - future progression":"Locked metal doors - future progression",h);
   for(int side=-1;side<=1;side+=2){var leaf=Group(side<0?"Left door - slide outward to open":"Right door - slide outward to open",doors);leaf.localPosition=new Vector3(side*2.5f,0,15.35f);
    Box("Solid closed leaf",leaf,new Vector3(0,4.48f,0),new Vector3(4.98f,8.95f,.24f),i<4?timber:metal);
    for(int k=0;k<16;k++)Box(i<4?"Weathered board":"Metal corrugation",leaf,new Vector3(-2.34f+k*.312f,4.48f,.15f),new Vector3(i<4?.27f:.045f,8.9f,.065f),i<4?cream:metal,false);
    foreach(float y in new[]{.45f,4.5f,8.45f})Box("Door cross rail",leaf,new Vector3(0,y,.24f),new Vector3(4.8f,.2f,.14f),i<4?timber:cream,false);
    if(i<4)Beam(leaf,new Vector3(-2.2f,.55f,.29f),new Vector3(2.2f,8.25f,.29f),.19f,timber);
    Box("Handle",leaf,new Vector3(-side*2.12f,3.8f,.37f),new Vector3(.11f,.6f,.13f),metal,false);
   }
   Box("Heavy sliding door track",doors,new Vector3(0,9.15f,.02f),new Vector3(20,.2f,.3f),metal,false);
   Box("Locking bar",doors,new Vector3(0,3.9f,.52f),new Vector3(1.2f,.16f,.12f),metal,false);Box("Visible padlock",doors,new Vector3(0,3.65f,.58f),new Vector3(.25f,.32f,.13f),cream,false);
   var sign=Group("Hangar number and locked sign",h);sign.localPosition=new Vector3(0,10.5f,15.55f);Box("Number plaque",sign,Vector3.zero,new Vector3(4,1.5f,.13f),metal,false);Text("HANGAR "+i,sign,new Vector3(0,.25f,.09f),2.1f,new Vector2(3.8f,.7f));Text("LOCKED",sign,new Vector3(0,-.42f,.09f),1.2f,new Vector2(3.8f,.5f));
   // Distinct roof finishes retain the original texture and structural material slots.
   var renderer=shell.Find("Roof").GetComponent<MeshRenderer>();var mats=renderer.sharedMaterials;
   for(int j=0;j<mats.Length;j++)if(mats[j].name.Contains("roof")){var copy=new Material(mats[j]){name="Hangar "+i+" roof finish"};copy.SetColor("_BaseColor",i==2?new Color(.37f,.22f,.12f):i==3?new Color(.28f,.31f,.33f):i==4?new Color(.13f,.16f,.18f):new Color(.23f,.28f,.24f));AssetDatabase.CreateAsset(copy,A+"/"+copy.name+".mat");mats[j]=copy;}renderer.sharedMaterials=mats;
  }
  var s=exp.Find("S - Farm supplies and cottage/Farm supplies shop");Text("FARM SUPPLIES",s,new Vector3(0,4.1f,4.28f),1.9f,new Vector2(6.4f,.7f));Text("BAGS  /  BOXES  /  TOOLS",s,new Vector3(0,2.65f,3.1f),.65f,new Vector2(6,.5f));Save();return "Four locked two-leaf doors authored: wood for 2/3, metal for 4/5. Door leaves remain independent for future opening. Roof finishes and numbered signs added.";
 }
 static void Fence(Transform parent,Vector3 a,Vector3 b,bool gate=false){float length=Vector3.Distance(a,b);int n=Mathf.CeilToInt(length/3);for(int i=0;i<=n;i++){var p=Vector3.Lerp(a,b,i/(float)n);p.y=H(p);Box("Fence post",parent,p+Vector3.up*.8f,new Vector3(.18f,1.6f,.18f),timber);if(i==n)continue;var q=Vector3.Lerp(a,b,(i+1)/(float)n);q.y=H(q);if(gate&&Mathf.Abs(i-n/2)<2)continue;foreach(float y in new[]{.55f,1.15f}){var rail=Box("Fence rail",parent,(p+q)*.5f+Vector3.up*y,new Vector3(.11f,.13f,Vector3.Distance(p,q)),timber);rail.transform.rotation=Quaternion.LookRotation(q-p);}}}
 public static string Surroundings(){Init();var farms=Group("12_Farmyards_and_boundaries",root);
  var points=new[]{new Vector3(55,0,112),new Vector3(-58,0,153),new Vector3(-94,0,233),new Vector3(62,0,206)};
  string[] names={"Timber homestead and hay paddock","Whitewashed market garden","Orchard farmstead","Village stonework and machinery yard"};
  for(int k=0;k<points.Length;k++){var p=points[k];var f=Group(names[k],farms);Prefab(k%2==0?"TFP_House_02A_Preset_1":"TFP_House_03A_Preset_1",f,p+new Vector3(0,0,12),k%2==0?180:0,.67f);
   Fence(f,p+new Vector3(-15,0,-12),p+new Vector3(15,0,-12),true);Fence(f,p+new Vector3(-15,0,-12),p+new Vector3(-15,0,24));Fence(f,p+new Vector3(15,0,-12),p+new Vector3(15,0,24));Fence(f,p+new Vector3(-15,0,24),p+new Vector3(15,0,24));
   for(int j=0;j<8;j++){var q=p+new Vector3(-10+(j%4)*6,0,-6+(j/4)*7);if(k==2)Prefab("TFP_Beech_Tree_02A",f,q,j*37,.55f);else if(k==0)Prefab("TFP_Hay_Bale_01A",f,q,j*19,1.1f);else if(k==1){Prefab("TFP_Wheat_Patch_01A",f,q,j*7,2.1f);}else Prefab(j%2==0?"TFP_Wooden_Crate_01A":"TFP_Metal_Barrel_01A",f,q,j*27,1.3f);}
   Prefab("TFP_Wooden_Pallet_01A",f,p+new Vector3(9,0,10));Prefab("TFP_Sack_Pile_01A",f,p+new Vector3(9,0,10));
  }
  // Paint small farm courts without changing the main road centerline.
  var td=terrain.terrainData;int nn=td.alphamapWidth;var alpha=td.GetAlphamaps(0,0,nn,nn);for(int z=0;z<nn;z++)for(int x=0;x<nn;x++){var p=terrain.transform.position+new Vector3(x/(float)(nn-1)*td.size.x,0,z/(float)(nn-1)*td.size.z);float w=0;foreach(var c in points){float d=Mathf.Max(Mathf.Abs(p.x-c.x)-13,Mathf.Abs(p.z-c.z-6)-16);w=Mathf.Max(w,1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(0,3,d)));}if(w<=0)continue;for(int l=0;l<td.alphamapLayers;l++)alpha[z,x,l]*=1-w;alpha[z,x,1]+=w*.35f;alpha[z,x,2]+=w*.15f;alpha[z,x,6]+=w*.5f;}td.SetAlphamaps(0,0,alpha);EditorUtility.SetDirty(td);
  var perimeter=Group("Continuous map boundary - collision",farms);foreach(var b in new[]{new Vector3(-181,38,122),new Vector3(181,38,122),new Vector3(0,38,-59),new Vector3(0,38,303)}){var g=Group("Map edge barrier",perimeter).gameObject;g.transform.position=b;g.AddComponent<BoxCollider>().size=Mathf.Abs(b.x)>100?new Vector3(2,100,366):new Vector3(364,100,2);}
  var edge=Group("Boundary split rail fences and hedgerow",farms);Fence(edge,new Vector3(-164,0,-41),new Vector3(164,0,-41));Fence(edge,new Vector3(-164,0,285),new Vector3(164,0,285));Fence(edge,new Vector3(-164,0,-41),new Vector3(-164,0,285));Fence(edge,new Vector3(164,0,-41),new Vector3(164,0,285));
  for(int j=0;j<104;j++){float a=j*Mathf.PI*2/104;var p=new Vector3(Mathf.Cos(a)*169,0,122+Mathf.Sin(a)*168);Prefab(j%3==0?"TFP_Rocks_01A":"TFP_Beech_Tree_02A",edge,p,j*137,j%3==0?2.7f:1.2f+(j%4)*.14f);}
  Backdrop(farms);Save();return "Four themed farmyards, continuous collision barriers, perimeter fences/trees and distant hill ring added.";
 }
 static void Backdrop(Transform parent){var vertices=new List<Vector3>();var uv=new List<Vector2>();var triangles=new List<int>();const int segments=192;float[] ring={0,24,70,135};for(int r=0;r<4;r++)for(int i=0;i<segments;i++){float t=i/(float)segments*4;int s=Mathf.FloorToInt(t);float f=t-s;Vector3 p=s==0?new Vector3(Mathf.Lerp(-192,192,f),0,-70):s==1?new Vector3(192,0,Mathf.Lerp(-70,314,f)):s==2?new Vector3(Mathf.Lerp(192,-192,f),0,314):new Vector3(-192,0,Mathf.Lerp(314,-70,f));var dir=new Vector3(p.x/192,0,(p.z-122)/192);p+=dir*ring[r];p.y=r==0?H(p):24+r*8+Mathf.PerlinNoise(p.x*.013f+34,p.z*.013f+62)*(12+r*5);vertices.Add(p);uv.Add(new Vector2(p.x*.045f,p.z*.045f));}
  for(int r=0;r<3;r++)for(int i=0;i<segments;i++){int a=r*segments+i,b=r*segments+(i+1)%segments,c=a+segments,d=b+segments;triangles.AddRange(new[]{a,c,b,b,c,d});}
  var mesh=new Mesh{name="Distant rolling farm hills"};mesh.SetVertices(vertices);mesh.SetUVs(0,uv);mesh.SetTriangles(triangles,0);mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,A+"/Distant rolling hills.asset");var g=Group("Distant rolling hills - backdrop",parent);g.gameObject.AddComponent<MeshFilter>().sharedMesh=mesh;var m=new Material(Shader.Find("HDRP/Lit")){name="Distant hillside meadow"};m.SetColor("_BaseColor",new Color(.43f,.51f,.26f));m.SetTexture("_BaseColorMap",terrain.terrainData.terrainLayers[0].diffuseTexture);m.SetFloat("_Smoothness",.02f);m.SetFloat("_DoubleSidedEnable",1);HDMaterial.ValidateMaterial(m);AssetDatabase.CreateAsset(m,A+"/Distant hillside meadow.mat");g.gameObject.AddComponent<MeshRenderer>().sharedMaterial=m;
 }
